// Differential checks of FourSchemes.js against Lean, generated by leanscript --check
import * as M from "./FourSchemes.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("sumAcc(0n, 0n)", () => M.sumAcc(0n, 0n), "0", false);
check("sumAcc(0n, 2n)", () => M.sumAcc(0n, 2n), "2", false);
check("sumAcc(1n, 1n)", () => M.sumAcc(1n, 1n), "2", false);
check("sumAcc(2n, 0n)", () => M.sumAcc(2n, 0n), "3", false);
check("sumAcc(0n, 13n)", () => M.sumAcc(0n, 13n), "13", false);
check("sumAcc(1n, 5n)", () => M.sumAcc(1n, 5n), "6", false);
check("sumAcc(2n, 2n)", () => M.sumAcc(2n, 2n), "5", false);
check("sumAcc(5n, 1n)", () => M.sumAcc(5n, 1n), "16", false);
check("sumAcc(13n, 0n)", () => M.sumAcc(13n, 0n), "91", false);
check("sumAcc(2n, 13n)", () => M.sumAcc(2n, 13n), "16", false);
check("sumAcc(5n, 5n)", () => M.sumAcc(5n, 5n), "20", false);
check("sumAcc(13n, 2n)", () => M.sumAcc(13n, 2n), "93", false);
check("sumAcc(13n, 13n)", () => M.sumAcc(13n, 13n), "104", false);
check("factD(0n)", () => M.factD(0n), "1", false);
check("factD(1n)", () => M.factD(1n), "1", false);
check("factD(2n)", () => M.factD(2n), "2", false);
check("factD(5n)", () => M.factD(5n), "120", false);
check("factD(13n)", () => M.factD(13n), "6227020800", false);
check("gcdT(0n, 0n)", () => M.gcdT(0n, 0n), "0", false);
check("gcdT(0n, 2n)", () => M.gcdT(0n, 2n), "2", false);
check("gcdT(1n, 1n)", () => M.gcdT(1n, 1n), "1", false);
check("gcdT(2n, 0n)", () => M.gcdT(2n, 0n), "2", false);
check("gcdT(0n, 13n)", () => M.gcdT(0n, 13n), "13", false);
check("gcdT(1n, 5n)", () => M.gcdT(1n, 5n), "1", false);
check("gcdT(2n, 2n)", () => M.gcdT(2n, 2n), "2", false);
check("gcdT(5n, 1n)", () => M.gcdT(5n, 1n), "1", false);
check("gcdT(13n, 0n)", () => M.gcdT(13n, 0n), "13", false);
check("gcdT(2n, 13n)", () => M.gcdT(2n, 13n), "1", false);
check("gcdT(5n, 5n)", () => M.gcdT(5n, 5n), "5", false);
check("gcdT(13n, 2n)", () => M.gcdT(13n, 2n), "1", false);
check("gcdT(13n, 13n)", () => M.gcdT(13n, 13n), "13", false);
check("stepsDown(0n)", () => M.stepsDown(0n), "1", false);
check("stepsDown(1n)", () => M.stepsDown(1n), "1", false);
check("stepsDown(2n)", () => M.stepsDown(2n), "2", false);
check("stepsDown(5n)", () => M.stepsDown(5n), "3", false);
check("stepsDown(13n)", () => M.stepsDown(13n), "7", false);

console.log(`FourSchemes.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
